```python:word_count.py
def count_words(sentence):
    processed = ""
    for char in sentence:
        if char.isalnum() or char == "'":
            processed += char
        else:
            processed += " "

    tokens = processed.split()
    counts = {}
    for token in tokens:
        word = token.strip("'").lower()
        if word:
            counts[word] = counts.get(word, 0) + 1
    return counts
```
